package com.beatoflove.standardcalculator;
import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.text.*;import android.view.*;import android.widget.*;
class PanelUi {
 static final int BG=0xff0b141d,CARD=0xff102531,FUNC=0xff142735,KEY=0xff233441,BLUE=0xff35c6f4,WHITE=0xfff4f8ff,MUTE=0xff90a4b7,ERROR=0xffffba57;
 final Activity a; PanelUi(Activity a){this.a=a;}
 int dp(float d){return Math.round(d*a.getResources().getDisplayMetrics().density);}
 LinearLayout col(){LinearLayout l=new LinearLayout(a);l.setOrientation(1);return l;} LinearLayout row(){LinearLayout l=new LinearLayout(a);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 GradientDrawable bg(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(9));return d;}
 TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(a);t.setText(s);t.setTextColor(color);t.setTextSize(size);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(dp(5),dp(5),dp(5),dp(5));return t;}
 LinearLayout screen(LinearLayout parent,String title,String desc){parent.removeAllViews();ScrollView scroll=new ScrollView(a);parent.addView(scroll,new LinearLayout.LayoutParams(-1,-1));LinearLayout l=col();l.setPadding(dp(12),dp(8),dp(12),dp(18));scroll.addView(l);l.addView(text(title,24,WHITE,true));l.addView(text(desc,13,MUTE,false));return l;}
 void action(LinearLayout l,String title,Runnable r){TextView b=key(title,BLUE, BG,r);l.addView(b,new LinearLayout.LayoutParams(-1,dp(48)));}
 TextView key(String s,int color,int ink,Runnable r){TextView t=text(s,15,ink,true);t.setGravity(Gravity.CENTER);t.setBackground(bg(color));t.setOnClickListener(v->r.run());t.setFocusable(true);return t;}
 void keys(LinearLayout l,String[][] rows,java.util.function.Consumer<String> fn){for(String[] line:rows){LinearLayout r=row();l.addView(r);for(String k:line){int color=k.equals("=")?BLUE:k.matches("[0-9.]+")?KEY:FUNC;TextView b=key(k,color,k.equals("=")?BG:WHITE,()->fn.accept(k));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(48),1);p.setMargins(dp(2),dp(2),dp(2),dp(2));r.addView(b,p);}}}
 Spinner spin(LinearLayout l,String name,String[] options){l.addView(text(name,12,MUTE,false));Spinner s=new Spinner(a);ArrayAdapter<String> ad=new ArrayAdapter<String>(a,android.R.layout.simple_spinner_item,options){@Override public View getView(int p,View v,ViewGroup g){TextView t=(TextView)super.getView(p,v,g);t.setTextColor(WHITE);t.setPadding(dp(8),0,dp(8),0);return t;}@Override public View getDropDownView(int p,View v,ViewGroup g){TextView t=(TextView)super.getDropDownView(p,v,g);t.setTextColor(Color.BLACK);return t;}};ad.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(ad);s.setBackgroundTintList(android.content.res.ColorStateList.valueOf(MUTE));s.setPopupBackgroundDrawable(bg(WHITE));l.addView(s,new LinearLayout.LayoutParams(-1,dp(48)));return s;}
 void selected(Spinner s,Runnable r){s.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int i,long id){r.run();}public void onNothingSelected(AdapterView<?> p){}});}
 EditText input(LinearLayout l,String title,String value,boolean free){l.addView(text(title,12,MUTE,false));EditText e=new EditText(a);e.setTextColor(WHITE);e.setTextSize(19);e.setBackground(bg(FUNC));e.setPadding(dp(12),dp(8),dp(12),dp(8));e.setInputType(free?InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE:InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);e.setText(value);l.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
 TextView result(LinearLayout l){TextView t=text("—",24,BLUE,true);t.setBackground(bg(CARD));t.setGravity(Gravity.END);t.setTextIsSelectable(true);l.addView(t,new LinearLayout.LayoutParams(-1,-2));return t;}
 void watch(EditText e,Runnable r){e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){r.run();}public void afterTextChanged(Editable e){}});}
 void link(LinearLayout l,String label,String url){TextView t=text(label+" ↗",13,BLUE,true);l.addView(t);t.setOnClickListener(v->{try{a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(url)));}catch(Exception ignored){}});}
}
